package vn.svframe.svframemmo.manager;
import vn.svframe.svframelib.config.YamlLite;import java.io.*;import java.nio.file.*;import java.util.*;
public final class AttributeManager { public record Attribute(String id,Map<String,Object> raw){} private final Map<String,Attribute> values=new LinkedHashMap<>(); public void reload(Path dir)throws IOException{values.clear();if(!Files.isDirectory(dir))return;try(var s=Files.walk(dir)){for(Path p:s.filter(Files::isRegularFile).filter(x->x.toString().endsWith(".yml")).sorted().toList()){Map<String,Object> root=YamlLite.map(YamlLite.parse(p));for(var e:root.entrySet())if(e.getValue() instanceof Map<?,?> m){@SuppressWarnings("unchecked")Map<String,Object> raw=(Map<String,Object>)m;String id=e.getKey().toUpperCase(Locale.ROOT).replace('-','_');values.put(id,new Attribute(id,Map.copyOf(raw)));}}}}public Attribute get(String id){return id==null?null:values.get(id.toUpperCase(Locale.ROOT).replace('-','_'));}public Collection<Attribute> getAll(){return List.copyOf(values.values());}public int size(){return values.size();}}
